fn entities<'a>(database: &'a SqliteDatabase, table: &str, columns: usize, floats: &'static [FloatColumn], control: &mut SqliteSnapshotControl<'_>) -> Result<Entities<'a>, ValueError> {
    let rows = &database.table(table)?.rows;
